-gv|-gvalue
The -gvalue option overrides the generic value defined in the source code with the value
specified in the command line during runtime.
% simv -gv generic_name=value or
% simv -gvalue generic_name=value
library ieee;
use ieee.std_logic_1164.all;

entity test is
generic (
size : integer:= 8;
left : integer:= size-1;
right : natural := 0
);
port (
A : in bit_vector(left downto right)
);
end test;
architecture arch of test is
L1: process
report to_string(size);
report to_string(left) & " " & to_string(right);
report to_string(A);
end process L1;
end arch;
To override at runtime, execute the following commands:
% vhdlan test.vhd -vhdl08
% vcs test -debug_access+all -lca
% ./simv -gv size=16
