as vector in runtime. */
bool list_variables(VariableListT& varList);

/*return variable data type*/
SvType get_type();

/* Return the enum string value of variable. */
const char* get_enum_value();

/* Return enum value name of variable. */
const char* get_enum_name(const char* val);

/*set variable rand mode*/
bool set_rand_mode(RandE rt);

/* get variable rand mode */
RandModeE get_rand_mode();

/* Ret the rand_type of Variable object. */
RandE get_rand_type();

/* Check whether the Variable's value has 'X' or 'Z'. */
bool has_XorZ();

Constraint Represents constraint block and constraint.
enum class ConstraintE {BlockC, ExprC, DistC, IfC, ImplicationC,
SolveBeforeC, UniqueC, ForeachC};
enum class ConstraintModeE {Invalid, OnState, OffState};

/*return block name for constraint block (BlockC), else return
NULL.*/
const char* get_block_name();

/*decompile constraint content*/
const char* decompile();

/*return constraint type*/
ConstraintE get_constraint_type();

/*return constraint mode*/
ConstraintModeE get_constraint_mode();

/*list all associated variables of constraint*/
bool list_variables(VariableListT& varList);

/*list all constraints for constraint block (BlockC), else return
false*/
bool list_constraints(ConstraintListT& constrList);

/*return true if the constraint block is created in cpp
application*/
bool is_user_created();

/* Perform value distribution to the given user-created 'dist'
constraint prior to other existing dist constraints. If there are
multiple dist constraints on the same random variables, it shall
ensure that the value distribution to the user-created constraint
and weights in other related dist constraints shall be skipped.
Return true when the current constraint is a 'dist' constraint and
is user-created */
bool distribute_first();

Context Represents the information about randomize() call.
cumlRandomizeFailC, // randomize fails.
cumlRandomizeSuccessC, // randimize succeeds.
} cumlRandomizeRetStatus

/* Return unique id. */
size_t get_uid();

/* Return thread id. */
size_t get_thread_id();

/* Get the status of randomize when the current callback function
is called in the 'EndRandomizeC' mode (at the end of randomize()
method). */
cumlRandomizeRetStatus get_randomize_return_status();

/* Return source line number of the current context. */
size_t get_line_number();

/* Return context file name of the current context. */
const char* get_file_name();

/* Get the call stack from where the randomize() method is being
called. */
const char* get_call_stack();

/* Find SvClass by name. */
SvClass get_class_by_name(const char* className, const char*
scopeName = NULL);

/* List out all valid sv classes in the given scope. */
bool list_svclasses(SvClassListT& classList, const char* scopeName =
NULL);

/* Scan simulation options that are passed from the command line,
and find out the argument that the given 'opt_name' is specified
with. */
const char* get_simulation_argument(const char* opt_name);

/* Get simulation time. */
size_t get_simulation_time();

/* Get simulation time unit. */
int get_simulation_timeunit();

/* Disable callback function calls coming from root object's subtree
when there are random children under the root object starting from
randomize() call. */
bool disable_callback_in_subtree();

RandomObject Represents randomize object of SV class.
/* Check whether the current RandomObject is root object. */
bool is_root_object();

/* Get root object's name in the root_object.randomize() call. */
const char* get_root_object_name();

/* Return sv class of random object. */
SvClass get_class();

/* Check whether the current RandomObject is root object. */
bool is_root_object();

/* Get root object's name in the root_object.randomize() call. */
const char* get_root_object_name();

/* Return sv class of random object. */
SvClass get_class();

/* Return the current RNG state. */
const char* get_randstat();

/* Look up local variable by name. */
Variable find_variable_by_name(const char* varName);

/* Look up local constraint block by name. */
Constraint find_constraint_by_name(const char* constraintName);

/* List all variables with rand/randc type in current random object.
*/
bool list_variables(VariableListT& varList);

/* List all constraint blocks in current random object. */
bool list_constraints (ConstraintListT& constraintList);

/* List all rand/randc arrays in current random object. */
bool list_arrays(VariableListT& arrList);

/* Create constraint from constraint statement and add to problem.
*/
Constraint new_constraint(const char* cbName, const char* expr);

/* Delete constraint. */
Constraint delete_constraint(Constraint constraint);

/* Enable constraint in problem. */
Constraint enable_constraint(Constraint constraint);

/* Disable constraint in problem. */
Constraint disable_constraint(Constraint constraint);

/* Call solver on the given random object. */
bool solve();

/* Call solver on the given RandomObject. */
/* A list of conflicts is stored in argument list. */
bool solve(ConstraintListT& conflicts);

/* List dist constraints in the solving order. */
bool list_dist_order(ConstraintListT &distSolveOrder);

/* Skip the normal randomize in randomize() method. */
void skip_sv_randomize(bool skip);

