Case4: Echo resolves and targets when the ternary expression is assigned to the sampled
variable.

rand integer i1,i2;
integer i3;
bit cond;

cp1 : coverpoint (i3) {
bins s0 = {0};
bins s1 = {1};
bins s2 = {2};
bins s3 = {3};
}

end

i3 = (cond ? i1 : i2);
end

