converter.v
module logic_to_wrealsum (input logic l, output wrealsum wsum);
real rv = 0.0;
assign wsum = rv;
always @(l) begin
if (l === 1'b0) rv = 0.0;
else if (l === 1'b1) rv = 3.5;
else if (l === 1'bz) rv = `wrealZState;
else rv = `wrealXState;
end

module wrealsum_to_logic (input wrealsum wsum, output logic l);
always @(wsum) begin
if (wsum == `wrealXState) l = 1'bx;
else if (wsum == `wrealZState) l = 1'bz;
else if (wsum <= 0.5) l = 1'b0;
else if (wsum >= 3.5) l = 1'b1;

else l =
1'bx;
end

