Verilog-down interface modules
Verilog interface model generation supports SystemVerilog types real for input and output
ports.
Interface models based on PLI (-sysc=pli_if) option does not support real.
The following example illustrates the usage of double data type:
: File: sc_block.h
#ifndef sc_block_H
#define sc_block_H

SC_MODULE(sc_block)
{
sc_in<bool> clock;

Support for Floating-Point Data Type Double in SystemC/HDL Interface Model
sc_in<double> value1;
sc_in<double> value2;
sc_out<double> out1;
sc_out<double> out2;

SC_CTOR(sc_block):
clock("clock"),
value1("value1"),
value2("value2"),
out1("out1"),
out2("out2")

{
SC_METHOD(sc_block_action);
sensitive << value1 << value2;
}
void sc_block_action();

};

sc_block.cpp

#include <sc_block.h>

void sc_block::sc_block_action() {
out1 = value1.read();
out2 = value2.read();
}
