signal a,b,c,d:bit;
x1:veri port map(a,b,c);
x2:and1 port map(a,d);
process
variable asd : std_logic;
variable vce : std_logic_vector(0 to 5);
a<='0';b<='0';
wait for 5 ns;
a<='0';b<='1';
wait for 5 ns;
a<='1';b<='0';
wait for 5 ns;
a<='1';b<='1';
wait for 5 ns;
end process;
end test_ar;
