always @(posedge clk1) q1 <= d1;
always @(posedge clk) q2 <= d2;

module dev1(in);
always @ (posedge in)
begin:named
if ($activeinst("top.d0","top.d1"))
$display("%i");
if ($activescope("top.d0.block","top.d1.named"))
$display("%-i");
end
