Example 14 Design Testcase test.v

reg clk,rst,d;
wire q;

DUT dut (clk,rst,d,q);

always #1 clk = ~clk;

clk = 0 ; rst =0 ; d=0 ;

#5 force rst = 1;
#5 release rst ;
#10 force dut.q =1 ;
#10 release dut.q ;
#100 $finish ;
end

module DUT (clk,rst,d,q);
input clk,rst,d;
wire q;
reg q_reg;

assign q = q_reg;

