module memory_rtl (clk,reset,wr,addr,data_in,data_out);
input clk,reset;
input wr;
input [1:0] addr;
input [7:0] data_in;
output [7:0] data_out;
wire [7:0] data_out;
reg [7:0] mem [0:3];
reg [7:0] rdata;
reg out_enable;
assign data_out = out_enable ? rdata : 'bz;
always @(posedge clk or posedge reset)
if (reset) begin
mem[0] <= 8'b11000011;
mem[1] <= 8'b11010100;
mem[2] <= 8'b11110110;
mem[3] <= 8'b00110011;
end else if(wr)
mem[addr] <= data_in;
end
if(wr==0)
rdata <= mem[addr];
out_enable <= 1'b1;
end
else out_enable <=1'b0;
end

//testcase.sv
===============
reg reset,wr;
reg [1:0] addr;
reg [7:0] data_in;
wire [7:0] data_out;
always #5 clk++;
memory_rtl inst(clk,reset,wr,addr,data_in,data_out);
reset = 1'b1;
#3;
reset = 1'b0;

$display("/*****reading from memory location*****/");
wr = 1'b0;
addr = 2'b0x;
@(negedge clk);
$display("addr : %b data_out : %b",addr,data_out);
addr = 2'b1x;
@(negedge clk);
$display("addr : %b data_out : %b",addr,data_out);
$display("/*****writing to memory location*****/");
wr = 1'b1;
addr = 2'b0x;
data_in = 8'b11010100;
@(negedge clk);
$display("addr : %b mem[0] : %b mem[1] : %b mem[2] :
%b mem[3] : %b",addr,top.inst.mem[0],top.inst.mem[1],
top.inst.mem[2],top.inst.mem[3]);
addr = 2'b1x;
data_in = 8'b11000100;
@(negedge clk);
$display("addr : %b mem[0] : %b mem[1] : %b mem[2] :
%b mem[3] : %b",addr,top.inst.mem[0],top.inst.mem[1],
top.inst.mem[2],top.inst.mem[3]);
end
