logic valid[2];

task automatic touch_task(ref logic valid);
@(valid) begin
end

module tb_top;
simple_if phy_if();
virtual simple_if virt_inst[2];

cls c = new;
phy_if.valid[0] = 1'b0;
virt_inst[0] = phy_if;
#1;
c.touch_task(tb_top.virt_inst[0].valid[0]);
end
#2;
virt_inst[0].valid[0] = 1'b1;
end
join
end
assert(count == 1) $display ("Passed!");
else $display ("Failed!");
end

