Example 119 Bit-Stream Structure Cast to String
typedef struct {int i; int j;} ST;
string s1;
ST c;
string s0;
always @(c.i) count++;
s0 = "helloday";
#1;
c = {>>8{s0}};
s1 = string'(c);
s0 = "weakarea";
#1;
c = {>>8{s0}};
s1 = string'(c);
#1;
if (count == 2) $display("Test Passed :-)");
else $display("Test Failed :-)");

end
Test Passed :-)
Time: 3
