function foo;
for (int i=0; i<2; i++)
for (int j=0; j<3; j++)
unique case (a[i][j])
0: b[i][j] = 1'b0;
1: b[i][j] = c[i][j];
endfunction : foo

for(i=0; i<4; i++) begin
if (i==2)
foo();
end
end

a = 6'b00x011;
end

