constraint cons2{…}
// Wrong usage: cons2 is specified final in A

constraint cons4{…}
// Wrong usage: A::cons4 is specified final
endclass : B

class C extends base;
constraint :initial cons2{…}
// Wrong usage: cons2 is an override from base::cons2

extern constraint :initial cons5;
// Correct usage: cons5 is not an override
endclass : C

constraint C::cons5{…}
// Correct usage: external method definitions do not declare override
specifiers
